CREATE TABLE `hraci` (
  `id` int(11) NOT NULL,
  `jmeno` varchar(70) collate utf8_czech_ci default NULL,
  `cislo` tinyint(4) NOT NULL,
  `vek` tinyint(4) NOT NULL,
  `vyska` tinyint(3) unsigned NOT NULL,
  `vaha` tinyint(3) unsigned NOT NULL,
  `value` int(11) NOT NULL,
  `salary` mediumint(9) NOT NULL,
  `country` varchar(3) character set utf8 NOT NULL,
  `druh_zraneni` varchar(10) collate utf8_czech_ci default NULL,
  `doba_zraneni` tinyint(4) NOT NULL,
  `junior` tinyint(4) NOT NULL,
  `team` int(11) NOT NULL,
  PRIMARY KEY  (`id`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8 COLLATE=utf8_czech_ci;



